package vn.nanase.hako;
import android.app.*;import android.app.job.*;import android.content.*;import android.os.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Deterministic transport fixtures: no account, network, or Gecko engine required. */
public final class ReadQueueWorkflowTest extends Instrumentation {
 int checks,serial;Context c;Store s;boolean online=true;String failing="",replace="",noButton="",newText="",stop="";int actions,catalogs;CountDownLatch entered,release;AtomicInteger simultaneous=new AtomicInteger(),maximum=new AtomicInteger();
 void check(boolean ok,String label){checks++;if(!ok)throw new AssertionError(label);Bundle out=new Bundle();out.putString("stream","PASS "+label+"\n");sendStatus(0,out);}
 public void onCreate(Bundle args){super.onCreate(args);start();}
 String fixture()throws Exception{String id="truyen-"+(990390+(serial++));String url="https://docln.sbs/truyen/"+id.substring(7)+"-fixture";s.putBook(new HakoParser.Link(id,"Fixture",url));List<HakoParser.Link> a=new ArrayList<>();a.add(new HakoParser.Link(id+"-1","Chương 1",url+"/c1-fixture"));s.catalog(id,a);s.followed(id,true,0);Store.write(s.html(id+"-1"),"<p>Nội dung chương chữ hợp lệ cho kiểm tra hàng chờ đã đọc hết.</p>");s.state(id+"-1",true,"");s.completeThrough(id,id+"-1");return id;}
 void extra(String id)throws Exception{List<HakoParser.Link> a=new ArrayList<>();for(Store.Chapter ch:s.chapters(id))a.add(new HakoParser.Link(ch.id,ch.title,ch.url));a.add(new HakoParser.Link(id+"-2","Chương 2",s.book(id).url+"/c2-fixture"));s.catalog(id,a);Store.write(s.html(id+"-2"),"<p>Nội dung chương mới cần đọc trước khi đánh dấu đọc hết.</p>");s.state(id+"-2",true,"");}
 void idle()throws Exception{java.lang.reflect.Field f=ReadSync.class.getDeclaredField("gate"),a=ReadSync.class.getDeclaredField("workerActive");f.setAccessible(true);a.setAccessible(true);Object lock=f.get(null);long end=SystemClock.elapsedRealtime()+8000;synchronized(lock){while(a.getBoolean(null)){long remaining=end-SystemClock.elapsedRealtime();if(remaining<=0)throw new AssertionError("Read worker failed to release");lock.wait(remaining);}}}
 String state(String id)throws Exception{return ReadSync.report(c).getJSONObject("states").getJSONObject(id).getString("state");}
 public void onStart(){Bundle result=new Bundle();ReadSync.Web original=ReadSync.web;try{
  c=getTargetContext();Diagnostics.start(c);s=Store.get(c);c.getSharedPreferences("settings",0).edit().putString("origin","https://docln.sbs").putBoolean("sync_paused",false).commit();Repository.init(c);Repository.cancel.set(false);
  ReadSync.web=new ReadSync.Web(){public boolean connected(Context x){return online;}public void catalog(Context x,Store.Book b)throws Exception{
   int active=simultaneous.incrementAndGet();maximum.updateAndGet(n->Math.max(n,active));try{catalogs++;if(b.id.equals(stop)){java.lang.reflect.Field token=ReadSync.class.getDeclaredField("stopped");token.setAccessible(true);((ThreadLocal<AtomicBoolean>)token.get(null)).set(new AtomicBoolean(true));}if(b.id.equals(newText)){newText="";extra(b.id);}if(entered!=null){entered.countDown();if(!release.await(5,TimeUnit.SECONDS))throw new AssertionError("Fixture handoff timeout");}if(b.id.equals(failing))throw new java.io.IOException("fixture");org.json.JSONArray ids=new org.json.JSONArray();for(Store.Chapter ch:s.chapters(b.id))ids.put(ch.id);c.getSharedPreferences("settings",0).edit().putString("server_catalog_"+b.id,ids.toString()).putBoolean("catalog_failed_"+b.id,false).commit();}finally{simultaneous.decrementAndGet();}}
   public String action(Context x,String id)throws Exception{actions++;if(id.equals(noButton))return "NO_READ_BUTTON";if(id.equals(replace)){s.resetUnreadForFull(id);s.completeThrough(id,id+"-1");}return "OK_BUTTON_GONE";}};
  String stale=fixture();extra(stale);check(s.queued(stale)&&s.unread(stale)==1,"New local text leaves old completion request available for reconciliation");
  c.getSharedPreferences("settings",0).edit().putBoolean("sync_paused",true).commit();ReadSync.process(c);check(!s.queued(stale)&&state(stale).equals("NEW_UNREAD"),"All-stale queue is cleaned before eligibility and pause exit");
  String paused=fixture();ReadSync.process(c);check(s.queued(paused)&&state(paused).equals("PAUSED"),"Pause is visible and preserves durable completion");check(actions==0,"Paused worker performs no remote action");
  c.getSharedPreferences("settings",0).edit().putBoolean("sync_paused",false).commit();online=false;ReadSync.process(c);check(state(paused).equals("WAIT_NETWORK"),"Offline completion reports WAIT_NETWORK");check(ReadSync.report(c).getJSONObject("states").getJSONObject(paused).getInt("attempts")==0,"No network means no verification attempt");
  online=true;Repository.busy.set(true);ReadSync.process(c);check(state(paused).equals("WAIT_BUSY")&&s.queued(paused),"Busy owner preserves request and reports WAIT_BUSY");
  Repository.busy.set(false);ReadSync.ownerReleased(c,"fixture_owner_release");idle();check(!s.queued(paused)&&state(paused).equals("SENT"),"Owner release triggers send without shelf import");check(ReadSync.report(c).getJSONObject("states").getJSONObject(paused).getInt("attempts")==1,"Terminal state retains actual attempt count");
  String legacy=fixture();Store.ReadRequest legacyRequest=s.readRequest(legacy);s.followed(legacy,false,0);check(s.reconcileReadRequest(legacyRequest).equals("ELIGIBLE")&&s.sameReadRequest(legacyRequest),"Stale followed flag does not delete durable completion");ReadSync.process(c);check(!s.queued(legacy),"Legacy request still verifies against fresh server catalog");
  String extended=fixture();Store.ReadRequest old=s.readRequest(extended);extra(extended);s.completeThrough(extended,extended+"-2");Store.ReadRequest newer=s.readRequest(extended);check(!s.sameReadRequest(old)&&!s.retireReadRequest(old,true)&&s.sameReadRequest(newer),"Old generation cannot consume newer completion");check(s.reconcileReadRequest(old).equals("GONE"),"Reconcile ignores obsolete generation");s.clearQueue(extended);
  c.getSharedPreferences("read_queue",0).edit().putString(extended,old.payload).commit();c.getSharedPreferences("settings",0).edit().putString("read_queue_tip_"+extended,old.tip).putString("read_queue_generation_"+extended,old.generation).commit();check(s.reconcileReadRequest(old).equals("EXTENDED")&&!s.sameReadRequest(old),"Legacy request with older tip extends to newer completed watermark");s.clearQueue(extended);
  String first=fixture(),second=fixture();failing=first;ReadSync.process(c);check(s.queued(first)&&!s.queued(second),"Failure of one title does not starve another title in same pass");check(state(first).equals("WAIT_RETRY"),"I/O failure is explicit and retryable");failing="";
  JobScheduler scheduler=c.getSystemService(JobScheduler.class);scheduler.cancel(42);scheduler.schedule(new JobInfo.Builder(42,new ComponentName(c,ReadSync.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setMinimumLatency(4*60*60*1000L).setPersisted(true).build());
  check(scheduler.getPendingJob(42)!=null,"Fixture installs delayed Job 42 before new event");ReadSync.kick(c,"new_completion_over_old_backoff");idle();check(!s.queued(first),"New event bypasses pre-existing delayed Job 42");check(scheduler.getPendingJob(42)==null,"Empty queue clears obsolete durable fallback");
  String concurrent=fixture();entered=new CountDownLatch(1);release=new CountDownLatch(1);ReadSync.kick(c,"first");check(entered.await(5,TimeUnit.SECONDS),"First event owns transport");for(int n=0;n<20;n++)ReadSync.kick(c,"coalesced");release.countDown();idle();entered=null;release=null;check(maximum.get()==1&&!s.queued(concurrent),"Concurrent events share one worker and never overlap transport");
  String race=fixture();replace=race;Store.ReadRequest captured=s.readRequest(race);ReadSync.process(c);check(s.queued(race)&&!s.sameReadRequest(captured),"Reply to old generation cannot retire request recreated during action");replace="";ReadSync.process(c);check(!s.queued(race),"Replacement request can finish on next pass");
  String absent=fixture();noButton=absent;ReadSync.process(c);check(!s.queued(absent)&&state(absent).equals("NO_BUTTON"),"Verified absent read button retires pending");s.queueCaughtUp(absent);check(!s.queued(absent),"Same absent-button tip stays suppressed");noButton="";
  String fresh=fixture();newText=fresh;int before=actions;ReadSync.process(c);check(!s.queued(fresh)&&state(fresh).equals("NEW_UNREAD")&&actions==before,"New text discovered during fresh verification prevents sending");
  String cancelled=fixture();stop=cancelled;before=actions;ReadSync.process(c);check(s.queued(cancelled)&&actions==before&&!Repository.cancel.get(),"Stopped-job token blocks remote action without cancelling downloads globally");stop="";ReadSync.process(c);check(!s.queued(cancelled),"Stopped request remains usable for next event");
  org.json.JSONObject report=ReadSync.report(c);check(report.has("syncPaused")&&report.has("job42Pending")&&report.has("workerActive")&&report.has("lastScheduleAt")&&report.has("lastScheduleOutcome")&&report.has("lastProcessStartAt")&&report.has("lastProcessEndAt")&&report.has("lastProcessOutcome"),"Report exposes all seven requested telemetry groups");check(!report.getBoolean("workerActive")&&!Repository.busy.get(),"Completed pass releases worker and repository ownership");check(report.getJSONObject("states").length()<=24,"Business telemetry remains bounded");
  result.putString("stream","PASS TOTAL "+checks+" read-queue workflow checks\n");finish(0,result);
 }catch(Throwable e){result.putString("stream","FAIL "+e+"\n");finish(1,result);}finally{if(release!=null)release.countDown();ReadSync.web=original;Repository.busy.set(false);c.getSystemService(JobScheduler.class).cancel(42);}}
}
